package com.hmdp.ai.infrastructure.dify;
import com.fasterxml.jackson.databind.JsonNode;import com.hmdp.ai.domain.tool.*;import org.springframework.stereotype.Component;
@Component public class DifyToolProtocolAdapter implements ToolProtocolAdapter {private final DifyToolExecutor executor;public DifyToolProtocolAdapter(DifyToolExecutor executor){this.executor=executor;}public ToolProtocol protocol(){return ToolProtocol.DIFY;}public ToolResult execute(ToolDefinition d,ToolInvocation i,JsonNode c){long started=System.currentTimeMillis();try{return ToolResult.success(executor.execute(c,i.getInput(),i.getContext().getUserId(),i.getContext().getRunId(),d.getTimeoutMs()),System.currentTimeMillis()-started);}catch(Exception e){String code=code(e);return ToolResult.failure(ToolCallStatus.FAILED,code,"Dify execution failed",!code.equals("DIFY_PROVIDER_NOT_CONFIGURED"));}}private String code(Exception e){Throwable c=e;while(c!=null){if(c.getMessage()!=null&&c.getMessage().matches("[A-Z0-9_]+"))return c.getMessage();c=c.getCause();}return "DIFY_EXECUTION_FAILED";}}
